class Solution { public long maxTaxiEarnings(int n,int[][] rides){Arrays.sort(rides,Comparator.comparingInt(a->a[1]));long[] dp=new long[n+1];int index=0;for(int position=1;position<=n;position++){dp[position]=dp[position-1];while(index<rides.length&&rides[index][1]==position){int[] ride=rides[index++];dp[position]=Math.max(dp[position],dp[ride[0]]+ride[1]-ride[0]+ride[2]);}}return dp[n];} }
